import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from p13_kit import *
from p13_fig import *

p = newpack("class3-maths", "Mathematics — Class 3", "Class 3", "maths",
    "Class 3 lessons: numbers to 10 000, rounding, the four operations, times tables, fractions, length, mass, capacity, perimeter, time, money and simple data.",
    REF % "Level II (Class 3) — Mathematics")
R = p.programRef
NOTE = "Number range, methods and the order in which topics appear (e.g. long division, thirds and fifths) are to be checked against the official syllabus."

# ===================================================== numbers
ch = p.chapter("numbers", "Place value and rounding", R)
lesson(ch, "place-value-10000", "Numbers to 10 000", ["Read and write numbers to 10 000.", "Give the value of each digit."],
  [("definition", "Thousands", "Ten hundreds make **one thousand**. A four-digit number has **thousands, hundreds, tens and ones**. In 3 452: 3 thousands, 4 hundreds, 5 tens, 2 ones. That is 3000 + 400 + 50 + 2."),
   ("retenir", "Place value table", "Each digit has a **place** and a **value**. In 7 081 the digit 7 is worth 7000 and the 0 is in the hundreds place (no hundreds). 10 000 is ten thousands."),
   ("pieges", "Common mistakes", "- 2 005 is not 205.\n- Keep a zero for an empty place.\n- Write a space between thousands and hundreds: 4 560.")],
  [("Example 1", "Write 6 thousands, 2 hundreds, 0 tens and 9 ones.", ["6000 + 200 + 0 + 9.", "That is 6 209."], "6 209", table_fig([["Th", "H", "T", "O"], ["6", "2", "0", "9"]], 280, 70, 34)),
   ("Example 2", "What is the value of the 5 in 3 452?", ["The 5 is in the tens place.", "5 tens is 50."], "50", None)],
  (table_fig([["Th", "H", "T", "O"], ["3", "4", "5", "2"]], 280, 70, 34), "3 452 in a place value table.", "A table with columns thousands, hundreds, tens, ones and the digits 3, 4, 5, 2."),
  [("n", "4000 + 700 + 20 + 6 = ?", 4726, "4 726."), ("n", "What is the hundreds digit of the number 5 380?", 3, "The hundreds digit is 3."), ("m", "The value of 8 in 8 140 is...", "8000", ["800", "80", "8"], "Thousands place.")],
  [("n", "One more than 4 999 is...", 5000, "5 000."), ("x", "Match.", [("2000 + 30 + 4", "2 034"), ("2000 + 300 + 4", "2 304"), ("2000 + 300 + 40", "2 340"), ("2000 + 3", "2 003")], "Watch the zeros.")],
  ("p", "A cocoa farmer near Mbalmayo sells 3 245 kg of cocoa in a season.", [("n", "How many thousands in 3 245?", 3, "3."), ("n", "He sells 755 kg more. How many kg now? (3 245 + 755)", 3245 + 755, "4 000.", "kg")]),
  [("Class 3 maths place value: in 5 321 the 5 is worth...", "5000", ["500", "50", "5"], "Thousands."),
   ("Class 3 maths place value: 2000 + 500 + 6 equals...", "2 506", ["2 056", "256", "25 006"], "2 506."),
   ("Ten hundreds make...", "one thousand", ["ten", "one hundred", "ten thousand"], "1 000."),
   ("In 9 070 the tens digit is...", "7", ["9", "0", "70"], "7 tens."),
   ("The biggest 4-digit number is...", "9 999", ["9 000", "10 000", "1 000"], "9 999.")],
  [NOTE])

lesson(ch, "compare-round", "Comparing and rounding", ["Compare numbers up to 10 000.", "Round to the nearest 10 and 100."],
  [("definition", "Rounding", "To **round** a number means to change it to a nearby easy number. To round to the nearest 10, look at the ones digit. If it is 5 or more, round **up**. If it is less than 5, round **down**."),
   ("retenir", "Examples", "63 → 60 (3 is less than 5). 67 → 70. 350 → 400 to the nearest 100 (5 tens rounds up). 349 → 300."),
   ("pieges", "Common mistakes", "- 5 rounds up, not down.\n- Rounding to 100 looks at the tens digit.\n- Rounded numbers are only close, not exact.")],
  [("Example 1", "Round 46 to the nearest 10.", ["The ones digit is 6, which is 5 or more.", "Round up: 50."], "50", numline(40, 50, [46])),
   ("Example 2", "Round 2 370 to the nearest 100.", ["The tens digit is 7, which is 5 or more.", "Round up the hundreds: 2 400."], "2 400", None)],
  (numline(40, 50, [43]), "43 is closer to 40 than to 50.", "A number line from 40 to 50 with a red dot at 43."),
  [("n", "Round 84 to the nearest 10.", 80, "4 is less than 5, down."), ("n", "Round 75 to the nearest 10.", 80, "5 rounds up."), ("n", "Round 640 to the nearest 100.", 600, "4 tens: down.")],
  [("m", "Which number is greater?", "5 408", ["5 084", "4 850", "5 048"], "Compare: thousands 5, then hundreds 4 > 0."), ("n", "Round 1 560 to the nearest 100.", 1600, "6 tens: up.")],
  ("p", "A market trader in Garoua sells 348 tomatoes in a week.", [("n", "Round 348 to the nearest 10.", 350, "8 rounds up."), ("n", "Round 348 to the nearest 100.", 300, "4 tens: down.")]),
  [("Class 3 maths rounding: 38 rounded to the nearest 10 is...", "40", ["30", "35", "50"], "8 up."),
   ("Class 3 maths rounding: 612 rounded to the nearest 100 is...", "600", ["700", "610", "620"], "1 ten: down."),
   ("When the digit is 5 or more we round...", "up", ["down", "sideways", "never"], "Up."),
   ("Which is less: 4 999 or 5 001?", "4 999", ["5 001", "equal", "none"], "4 999."),
   ("Round 95 to the nearest 10.", "100", ["90", "95", "10"], "5 up.")],
  [], prereq=["class3-maths-place-value-10000"])

# ===================================================== operations
ch = p.chapter("operations", "The four operations", R)
lesson(ch, "add-sub-3digit", "Adding and subtracting 3- and 4-digit numbers", ["Add numbers with carrying.", "Subtract numbers with borrowing."],
  [("definition", "Column method", "Write the numbers in columns: ones under ones, tens under tens, hundreds under hundreds. Add or subtract from the right. Carry a ten when ones make 10 or more."),
   ("methode", "Subtract", "Subtract from the right. If the top digit is too small, **borrow** one from the next place. 502 − 267: borrow, then 12 − 7 = 5; 9 − 6 = 3; 4 − 2 = 2; answer 235."),
   ("pieges", "Common mistakes", "- Line up the digits.\n- Do not forget carried digits.\n- Check with the opposite operation.")],
  [("Example 1", "458 + 267 = ?", ["Ones: 8 + 7 = 15. Write 5, carry 1.", "Tens: 5 + 6 + 1 = 12. Write 2, carry 1. Hundreds: 4 + 2 + 1 = 7. Answer 725."], str(458 + 267), None),
   ("Example 2", "502 − 267 = ?", ["Borrow: 502 is 4 hundreds, 10 tens, 12 ones. 12 − 7 = 5.", "Tens: 9 tens are left (one was borrowed): 9 − 6 = 3. Hundreds: 4 − 2 = 2. Answer 235."], str(502 - 267), None)],
  (cards(["458", "+ 267", "= 725"], 3, 400, ch=40), "458 + 267 = 725.", "Three boxes showing 458 plus 267 equals 725."),
  [("n", "345 + 278 = ?", 345 + 278, "623."), ("n", "812 − 345 = ?", 812 - 345, "467."), ("n", "1 250 + 750 = ?", 1250 + 750, "2 000.")],
  [("n", "4 003 − 1 998 = ?", 4003 - 1998, "2 005."), ("n", "2 689 + 1 475 = ?", 2689 + 1475, "4 164.")],
  ("p", "A school in Bamenda collects money for a library. Class 3 gives 4 250 FCFA, Class 4 gives 5 675 FCFA.", [("n", "How much altogether?", 4250 + 5675, "9 925.", "FCFA"), ("n", "A set of books costs 8 500 FCFA. How much is left after buying it?", 4250 + 5675 - 8500, "9 925 − 8 500 = 1 425.", "FCFA")]),
  [("Class 3 maths columns: 326 + 135 equals...", "461", ["451", "361", "4 511"], "461."),
   ("Class 3 maths columns: 700 − 250 equals...", "450", ["550", "950", "350"], "450."),
   ("To check 800 − 300 = 500 we add...", "500 + 300", ["800 + 300", "500 − 300", "800 − 500 only"], "800."),
   ("999 + 1 equals...", "1 000", ["990", "9 910", "100"], "1 000."),
   ("Which is the right start when adding in columns?", "ones column", ["hundreds column", "thousands column", "the biggest digit"], "Right side first.")],
  [NOTE], prereq=["class3-maths-place-value-10000"])

lesson(ch, "times-tables", "Times tables 2 to 10", ["Know the multiplication tables up to 10 × 10.", "Use patterns to learn the facts."],
  [("definition", "Tables", "A times table is repeated adding. 6 × 4 = 24 because 4 + 4 + 4 + 4 + 4 + 4 = 24. Order does not matter: 6 × 4 = 4 × 6."),
   ("retenir", "Tricks", "× 9: the digits of the answer add to 9 (9 × 4 = 36: 3 + 6 = 9). × 5: ends in 0 or 5. × 10: add a zero. × 4: double and double again."),
   ("pieges", "Common mistakes", "- 7 × 8 = 56 (say 5, 6, 7, 8: 56 = 7 × 8).\n- 6 × 6 = 36.\n- Do not mix up 8 × 8 = 64 and 8 × 7 = 56.")],
  [("Example 1", "How many days in 4 weeks?", ["A week has 7 days.", "4 × 7 = 28."], str(4 * 7), array(4, 7)),
   ("Example 2", "A box holds 9 eggs. How many in 6 boxes?", ["6 × 9.", "6 × 9 = 54 (5 + 4 = 9)."], str(6 * 9), None)],
  (table_fig([["×", "6", "7", "8", "9"], ["6", "36", "42", "48", "54"], ["7", "42", "49", "56", "63"]], 400, 70, 32), "Part of the times table.", "A table of products of 6 and 7 with 6, 7, 8, 9."),
  [("n", "6 × 7 = ?", 42, "42."), ("n", "8 × 8 = ?", 64, "64."), ("n", "9 × 9 = ?", 81, "81.")],
  [("x", "Match.", [("7 × 6", "42"), ("8 × 5", "40"), ("9 × 3", "27"), ("4 × 12", "48")], "Use the tables."), ("m", "Which is NOT in the 4 times table?", "18", ["16", "24", "36"], "4 × 4 = 16, 4 × 6 = 24, 4 × 9 = 36; 18 is not.")],
  ("p", "A trader sells oranges in heaps of 8.", [("n", "How many oranges in 7 heaps?", 56, "7 × 8 = 56."), ("n", "Each orange costs 25 FCFA. What is the price of one heap? (8 × 25)", 200, "200.", "FCFA")]),
  [("Class 3 maths tables: 7 × 7 equals...", "49", ["42", "56", "77"], "49."),
   ("Class 3 maths tables: 9 × 5 equals...", "45", ["54", "14", "95"], "45."),
   ("6 × 8 equals...", "48", ["46", "54", "42"], "48."),
   ("The digits of the answers in the 9 times table (up to 10) add up to...", "9", ["10", "18 always", "3"], "9 × 3 = 27: 2 + 7 = 9."),
   ("12 × 2 equals...", "24", ["14", "122", "10"], "24.")],
  [NOTE], prereq=["class3-maths-add-sub-3digit"])

lesson(ch, "multiply-by-1digit", "Multiplying a 2- or 3-digit number by 1 digit", ["Multiply a bigger number by a small number.", "Carry in multiplication."],
  [("definition", "Method", "To multiply 23 × 4: multiply the ones: 3 × 4 = 12. Write 2, carry 1. Multiply the tens: 2 × 4 = 8, plus 1 = 9. Answer 92."),
   ("methode", "Break apart", "Or break 23 into 20 + 3. 20 × 4 = 80 and 3 × 4 = 12. Add: 80 + 12 = 92."),
   ("pieges", "Common mistakes", "- Do not forget the carried digit.\n- Multiply every digit.\n- 0 in the middle: 105 × 3 = 315.")],
  [("Example 1", "34 × 5 = ?", ["Ones: 4 × 5 = 20. Write 0, carry 2.", "Tens: 3 × 5 = 15, plus 2 = 17. Answer 170."], str(34 * 5), None),
   ("Example 2", "126 × 3 = ?", ["100 × 3 = 300, 20 × 3 = 60, 6 × 3 = 18.", "300 + 60 + 18 = 378."], str(126 * 3), None)],
  (cards(["23 × 4", "20 × 4 = 80", "3 × 4 = 12", "80 + 12 = 92"], 2, 400, ch=40), "Break apart: 23 × 4.", "Four boxes showing 23 times 4 broken into 80 and 12."),
  [("n", "23 × 3 = ?", 23 * 3, "69."), ("n", "45 × 2 = ?", 45 * 2, "90."), ("n", "112 × 4 = ?", 112 * 4, "448.")],
  [("n", "56 × 7 = ?", 56 * 7, "392."), ("n", "208 × 3 = ?", 208 * 3, "624.")],
  ("p", "A farmer in Buea packs 36 bananas in each box.", [("n", "How many bananas in 5 boxes?", 36 * 5, "180."), ("n", "Each box sells for 1 500 FCFA. How much for 5 boxes?", 1500 * 5, "7 500.", "FCFA")]),
  [("Class 3 maths multiplying: 12 × 4 equals...", "48", ["16", "124", "46"], "48."),
   ("Class 3 maths multiplying: 30 × 5 equals...", "150", ["35", "15", "1 500"], "150."),
   ("25 × 4 equals...", "100", ["29", "80", "1 000"], "100."),
   ("When multiplying 2-digit numbers by 1 digit we start with the...", "ones", ["hundreds", "answer", "biggest"], "Ones."),
   ("101 × 5 equals...", "505", ["55", "515", "1 005"], "505.")],
  [NOTE], prereq=["class3-maths-times-tables"])

lesson(ch, "division-remainders", "Division and remainders", ["Divide by 2 to 10.", "Understand a remainder."],
  [("definition", "Division", "Division is sharing into equal groups. 24 ÷ 6 = 4 because 6 × 4 = 24. Sometimes there is something left over. This is the **remainder**."),
   ("retenir", "Remainder", "17 ÷ 5: 5 × 3 = 15 and 2 are left. So 17 ÷ 5 = 3 remainder 2 (r 2). The remainder must be smaller than the number you divide by."),
   ("pieges", "Common mistakes", "- 8 ÷ 2 is not 2 ÷ 8.\n- The remainder is smaller than the divisor.\n- Check: 3 × 5 + 2 = 17.")],
  [("Example 1", "36 ÷ 4 = ?", ["Think: 4 × 9 = 36.", "So 36 ÷ 4 = 9."], str(36 // 4), None),
   ("Example 2", "23 ÷ 5 = ?", ["5 × 4 = 20. 23 − 20 = 3.", "So 23 ÷ 5 = 4 remainder 3."], "4 r 3", None)],
  (count(23, "circle", "orange", 5, 300, 150), "23 balls in groups of 5: 4 groups and 3 left over.", "Twenty-three orange circles in rows of five."),
  [("n", "42 ÷ 6 = ?", 7, "6 × 7 = 42."), ("n", "81 ÷ 9 = ?", 9, "9 × 9 = 81."), ("n", "What is the remainder of 17 ÷ 5?", 2, "2.")],
  [("n", "What is the remainder of 29 ÷ 4?", 29 % 4, "4 × 7 = 28; 1 left."), ("n", "96 ÷ 4 = ?", 96 // 4, "24.")],
  ("p", "A teacher has 47 pencils for 5 groups.", [("n", "How many pencils does each group get?", 47 // 5, "47 ÷ 5 = 9 r 2."), ("n", "How many pencils are left over?", 47 % 5, "2.")]),
  [("Class 3 maths division: 45 ÷ 9 equals...", "5", ["4", "6", "36"], "5."),
   ("Class 3 maths division: 20 ÷ 3 gives remainder...", "2", ["0", "1", "6"], "20 = 6 × 3 + 2."),
   ("If 7 × 8 = 56, then 56 ÷ 8 =", "7", ["8", "48", "64"], "7."),
   ("A remainder is smaller than the...", "number we divide by", ["answer times 2", "biggest number", "total"], "Smaller than divisor."),
   ("63 ÷ 7 equals...", "9", ["8", "7", "56"], "9.")],
  [NOTE], prereq=["class3-maths-times-tables"])

lesson(ch, "word-problems", "Problems with all four operations", ["Choose the right operation.", "Solve problems with two steps."],
  [("methode", "Steps", "1. Read the problem two times. 2. Underline the numbers. 3. Choose + − × or ÷. 4. Work it out. 5. Write the answer with the unit. 6. Ask: is it sensible?"),
   ("retenir", "Which operation?", "Put together: **add**. Take away or compare: **subtract**. Equal groups: **multiply**. Share equally: **divide**."),
   ("pieges", "Common mistakes", "- Do not use every number just because it is there.\n- Do the steps in order.\n- Check with an estimate.")],
  [("Example 1", "A box holds 12 bottles. A shop buys 6 boxes and sells 50 bottles. How many bottles are left?", ["Bottles bought: 12 × 6 = 72.", "Left: 72 − 50 = 22."], str(12 * 6 - 50), None),
   ("Example 2", "84 pupils go on a trip. Each bus takes 30. How many buses? ", ["84 ÷ 30 = 2 remainder 24.", "24 pupils still need a bus, so we need 3 buses."], "3 buses", None)],
  (cards(["add: together", "subtract: left", "multiply: groups", "divide: share"], 2, 400, ch=38), "Which operation?", "Four boxes with clue words for the four operations."),
  [("n", "A packet has 8 biscuits. How many in 7 packets?", 56, "56."), ("n", "72 mangoes are shared by 9 women. How many each?", 8, "8."), ("n", "A girl has 235 FCFA and gets 150 FCFA. How much has she?", 385, "385.", "FCFA")],
  [("n", "Kofi buys 3 books at 450 FCFA each. How much does he pay?", 3 * 450, "1 350.", "FCFA"), ("n", "He pays with 2 000 FCFA. How much is his change?", 2000 - 3 * 450, "650.", "FCFA")],
  ("p", "A baker in Douala bakes 125 loaves each day for 4 days.", [("n", "How many loaves in 4 days?", 125 * 4, "500."), ("n", "She sells 380 loaves. How many are left?", 125 * 4 - 380, "120.")]),
  [("Class 3 maths problems: equal groups tell us to...", "multiply", ["add only", "subtract", "round"], "Multiply."),
   ("Class 3 maths problems: a total shared equally tells us to...", "divide", ["multiply", "add", "double"], "Divide."),
   ("5 bags with 20 nuts each. How many nuts?", "100", ["25", "15", "4"], "100."),
   ("150 − 75 equals...", "75", ["225", "85", "65"], "75."),
   ("At the end of a problem, we should...", "write the answer with its unit", ["write nothing", "add 10", "erase the working"], "Unit.")],
  [], prereq=["class3-maths-division-remainders", "class3-maths-multiply-by-1digit"])

# ===================================================== fractions
ch = p.chapter("fractions", "Fractions", R)
lesson(ch, "fractions-basic", "Fractions of a whole", ["Name halves, thirds, quarters and fifths.", "Read and write a fraction."],
  [("definition", "Fraction", "A **fraction** is a part of a whole. The whole is cut into **equal** parts. The bottom number (denominator) says how many equal parts. The top number (numerator) says how many parts we take. 3/4 means 3 of 4 equal parts."),
   ("retenir", "Names", "2 parts: halves. 3 parts: thirds. 4 parts: quarters. 5 parts: fifths. 1/2, 1/3, 1/4, 1/5 are **unit fractions**."),
   ("pieges", "Common mistakes", "- Parts must be equal.\n- 1/3 is bigger than 1/4.\n- The bottom number is not the number of parts we take.")],
  [("Example 1", "What fraction is coloured?", ["The bar has 5 equal parts.", "2 parts are coloured. So 2/5."], "2/5", frac_bar(5, 2)),
   ("Example 2", "A plantain is cut into 4 equal parts. Ada eats 3. What fraction did she eat?", ["The whole has 4 parts.", "She ate 3 of them: 3/4."], "3/4", frac_bar(4, 3))],
  (frac_bar(3, 1), "1/3 of the bar is coloured.", "A bar with 3 parts, one coloured."),
  [("m", "In 3/5 the bottom number is...", "5", ["3", "2", "8"], "5 equal parts."), ("m", "What fraction is shown?", "3/4", ["1/4", "4/3", "3/7"], "3 of 4 parts.", {"figure": frac_bar(4, 3)}), ("m", "Which is the bigger part: 1/2 or 1/4?", "1/2", ["1/4", "they are equal", "none"], "Fewer parts means bigger parts.")],
  [("n", "A cake is cut into 8 equal slices. You eat 3. How many slices are left?", 5, "8 − 3 = 5."), ("x", "Match the fraction with its name.", [("1/2", "a half"), ("1/3", "a third"), ("1/4", "a quarter"), ("1/5", "a fifth")], "Names of unit fractions.")],
  ("p", "Mama cuts a loaf into 6 equal pieces.", [("n", "She gives 2 pieces to Bih. What is the top number of the fraction she gave?", 2, "2/6."), ("n", "How many pieces are left?", 4, "6 − 2 = 4.")]),
  [("Class 3 maths fractions: the top number of a fraction is called the...", "numerator", ["denominator", "sum", "whole"], "Numerator."),
   ("Class 3 maths fractions: 2/3 means 2 of...", "3 equal parts", ["2 equal parts", "5 parts", "3 pieces always"], "3 equal parts."),
   ("A pizza is cut into 8 equal parts. Each part is...", "1/8", ["8/1", "1/4", "1/2"], "One eighth."),
   ("Which is the biggest: 1/2, 1/3, 1/5?", "1/2", ["1/3", "1/5", "all equal"], "Half."),
   ("The bottom number is called the...", "denominator", ["numerator", "product", "remainder"], "Denominator.")],
  ["Fractions with denominators up to 10 are assumed; check the syllabus limit."], prereq=["class3-maths-division-remainders"])

lesson(ch, "fractions-equal-compare", "Equal fractions and fractions of a number", ["Show that 1/2 = 2/4.", "Find a fraction of a number."],
  [("definition", "Equal fractions", "Different fractions can show the same amount. 1/2 = 2/4 = 3/6. Look at the bars: the coloured part is the same size."),
   ("methode", "Fraction of a number", "To find 1/4 of 20: divide by 4. 20 ÷ 4 = 5. To find 3/4 of 20: find 1/4 (5) and multiply by 3: 15."),
   ("pieges", "Common mistakes", "- 1/2 does not equal 1/4.\n- To find 3/5 of a number, divide by 5 first, then multiply by 3.\n- Same denominator: the bigger numerator is the bigger fraction.")],
  [("Example 1", "Find 1/5 of 30 mangoes.", ["Divide 30 by 5.", "30 ÷ 5 = 6."], str(30 // 5), None),
   ("Example 2", "Find 3/4 of 28.", ["1/4 of 28 is 28 ÷ 4 = 7.", "3/4 is 3 × 7 = 21."], str(28 // 4 * 3), None)],
  (shapes([RECT(10, 10, 160, 40, fill="white")] + [RECT(10, 10, 80, 40, fill="orange"), LINE(90, 10, 90, 50), T(90, 70, "1/2", 14, bold=True), RECT(10, 90, 160, 40, fill="white"), RECT(10, 90, 80, 40, fill="orange")] + [LINE(10 + 40 * i, 90, 10 + 40 * i, 130) for i in range(1, 4)] + [T(90, 150, "2/4", 14, bold=True)], 200, 160), "1/2 and 2/4 cover the same part.", "Two bars: one cut in two with one coloured half, one cut in four with two quarters coloured."),
  [("n", "1/3 of 12 = ?", 4, "12 ÷ 3."), ("n", "1/2 of 50 = ?", 25, "50 ÷ 2."), ("n", "3/5 of 20 = ?", 12, "20 ÷ 5 = 4; 4 × 3 = 12.")],
  [("m", "Which fraction equals 1/2?", "4/8", ["1/4", "2/3", "3/8"], "4/8 is half of 8."), ("n", "2/3 of 18 = ?", 12, "18 ÷ 3 = 6; × 2 = 12.")],
  ("p", "A farmer in Bafoussam has 40 chickens.", [("n", "1/4 of them are cocks. How many cocks?", 10, "40 ÷ 4."), ("n", "3/5 of them are white. How many are white?", 24, "40 ÷ 5 = 8; × 3 = 24.")]),
  [("Class 3 maths equal fractions: 1/2 is equal to...", "2/4", ["1/4", "2/3", "3/4"], "2/4."),
   ("Class 3 maths fraction of a number: 1/4 of 16 is...", "4", ["8", "12", "2"], "16 ÷ 4."),
   ("3/4 of 8 is...", "6", ["2", "4", "3"], "8 ÷ 4 = 2; 3 × 2 = 6."),
   ("Which fraction is the biggest: 3/8, 5/8, 1/8?", "5/8", ["3/8", "1/8", "equal"], "Same bottom: bigger top."),
   ("1/10 of 100 is...", "10", ["1", "100", "50"], "100 ÷ 10.")],
  [], prereq=["class3-maths-fractions-basic"])

# ===================================================== measures
