ch = p.chapter("data", "Simple data", R)
fruit = [("Mango", 6), ("Orange", 4), ("Banana", 5)]
lesson(ch, "pictographs", "Pictographs and tally charts", ["Read a pictograph.", "Make a tally chart."],
  [("definition", "Pictograph", "A **pictograph** uses pictures or symbols to show numbers. A **key** tells what each symbol means. Here each circle stands for 2 pupils."),
   ("retenir", "Tally", "A **tally chart** counts with marks. We write one mark for each thing. We cross four marks with a fifth. 5 = a bundle of five."),
   ("pieges", "Common mistakes", "- Read the key. One symbol may stand for more than one.\n- Count each symbol.\n- Half a symbol is half the number.")],
  [("Example 1", "Each circle is 2 pupils. Mango has 6 circles. How many pupils like mango?", ["Count the circles: 6.", "6 × 2 = 12 pupils."], "12 pupils", picto([("Mango", 6), ("Orange", 4), ("Banana", 5)], key="= 2 pupils")),
   ("Example 2", "How many pupils like orange?", ["Orange has 4 circles.", "4 × 2 = 8 pupils."], "8 pupils", None)],
  (picto([("Mango", 6), ("Orange", 4), ("Banana", 5)], key="= 2 pupils"), "Favourite fruit of Class 3 pupils. Each circle is 2 pupils.", "A pictograph with rows for mango (6 circles), orange (4 circles) and banana (5 circles)."),
  [("n", "In the pictograph, how many pupils like banana?", 10, "5 circles × 2 = 10.", None, {"figure": picto([("Mango", 6), ("Orange", 4), ("Banana", 5)], key="= 2 pupils")}), ("m", "Which fruit do most pupils like?", "Mango", ["Orange", "Banana", "They are equal"], "6 circles is the most.", {"figure": picto([("Mango", 6), ("Orange", 4), ("Banana", 5)], key="= 2 pupils")}), ("n", "How many pupils in all? (12 + 8 + 10)", 30, "30.")],
  [("n", "How many more pupils like mango than orange?", 4, "12 − 8 = 4."), ("t", "A key tells us what each symbol means.", True, "True.")],
  ("p", "A teacher draws a pictograph of the pets at home. Each circle means 3 pets. Dogs: 4 circles. Cats: 3 circles. Hens: 5 circles.", [("n", "How many dogs?", 12, "4 × 3."), ("n", "How many cats?", 9, "3 × 3."), ("n", "How many more hens than cats?", 6, "15 − 9.")]),
  [("Class 3 maths pictographs: the key tells us...", "what each symbol means", ["the colour", "the day", "the title"], "Key."),
   ("Class 3 maths pictographs: if one circle means 5 and there are 3 circles, the number is...", "15", ["8", "5", "3"], "3 × 5."),
   ("A tally mark group of 5 is drawn as...", "four marks crossed by one", ["five circles", "a number five", "one tall bar"], "Bundle of 5."),
   ("A pictograph uses...", "pictures or symbols", ["only words", "only coins", "only a clock"], "Symbols."),
   ("Half a symbol that stands for 4 means...", "2", ["4", "8", "1"], "Half of 4.")],
  ["The `circle` symbol is a stand-in for a picture of a fruit/person."])

bd = [("Mon", 3), ("Tue", 5), ("Wed", 4), ("Thu", 7), ("Fri", 2)]
lesson(ch, "bar-charts", "Reading bar charts", ["Read values from a bar chart.", "Compare bars."],
  [("definition", "Bar chart", "A **bar chart** uses bars to show numbers. A taller bar means a bigger number. The labels under the bars tell what each bar is."),
   ("methode", "Read it", "1. Read the title. 2. Read the labels. 3. Look at the top of the bar and read across to the numbers. 4. Compare the bars."),
   ("pieges", "Common mistakes", "- Read the top of the bar, not the middle.\n- The tallest bar is the biggest number.\n- Look at the unit.")],
  [("Example 1", "The chart shows pupils absent each day. How many were absent on Thursday?", ["Find Thursday and look at the top of its bar.", "The bar is at 7."], "7 pupils", bars(bd + [], "pupils", 400, 240)),
   ("Example 2", "Which day had the fewest absent pupils?", ["Look for the shortest bar.", "Friday is the shortest."], "Friday", None)],
  (bars(bd, "pupils", 400, 240), "Pupils absent each day.", "A bar chart of absent pupils from Monday to Friday: 3, 5, 4, 7, 2."),
  [("n", "How many pupils were absent on Tuesday?", 5, "Read the Tuesday bar.", None, {"figure": bars(bd, "pupils")}), ("m", "Which day had the most absent pupils?", "Thursday", ["Monday", "Friday", "Wednesday"], "The tallest bar.", {"figure": bars(bd, "pupils")}), ("n", "How many pupils were absent over the whole week?", sum(v for _, v in bd), "3 + 5 + 4 + 7 + 2 = 21.")],
  [("n", "How many more were absent on Thursday than on Friday?", 5, "7 − 2.", None, {"figure": bars(bd, "pupils")}), ("t", "A taller bar shows a bigger number.", True, "True.")],
  ("p", "A Class 3 teacher counts the books each group read: Group A 12, Group B 8, Group C 15.", [("n", "How many books in all?", 35, "12 + 8 + 15."), ("n", "How many more did Group C read than Group B?", 7, "15 − 8.")]),
  [("Class 3 maths bar charts: the tallest bar shows the...", "biggest number", ["smallest number", "title", "day"], "Biggest."),
   ("Class 3 maths bar charts: we read a bar's number at its...", "top", ["bottom", "label colour", "side"], "Top."),
   ("To compare two bars we look at which is...", "taller", ["wider", "darker", "left"], "Taller."),
   ("Bars of 4 and 7: the difference is...", "3", ["11", "28", "4"], "7 − 4."),
   ("The labels under the bars tell us...", "what each bar shows", ["how tall the bar is", "the price", "nothing"], "Labels.")],
  ["Check that the bars figure has headroom above the tallest bar (7)."], prereq=["class3-maths-pictographs"])

